'use client';

import { Button, Notice } from '@researchforge/ui';
import { useCallback, useEffect, useState } from 'react';
import { api } from '@/lib/api-client';

const SYNTHETIC_LABEL =
  'Synthetic dataset generated by ResearchForge. It must not be represented as collected experimental data.';

interface DatasetStudioProps {
  projectId: string;
  sectionId: string | null;
}

interface DatasetRow {
  id: string;
  name: string;
  synthetic: boolean;
  provenance_type: string;
  provenance_label: string;
  label_locked: boolean;
  random_seed: number | null;
  version?: {
    id: string;
    row_count: number;
    column_count: number;
    profile?: { preview_rows?: Record<string, unknown>[]; pii_warnings?: unknown[] };
  };
}

interface FigureRow {
  id: string;
  stable_id: string;
  number: number;
  title: string;
  kind: string;
  provenance_label: string;
  is_conceptual: boolean;
}

interface TableRow {
  id: string;
  stable_id: string;
  number: number;
  title: string;
  provenance_label: string;
}

export function DatasetStudio({ projectId, sectionId }: DatasetStudioProps) {
  const [datasets, setDatasets] = useState<DatasetRow[]>([]);
  const [figures, setFigures] = useState<FigureRow[]>([]);
  const [tables, setTables] = useState<TableRow[]>([]);
  const [limitations, setLimitations] = useState<string[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const [seed, setSeed] = useState(42);
  const [rows, setRows] = useState(50);

  const refresh = useCallback(async () => {
    const [ds, figs, tbls, lim] = await Promise.all([
      api.listDatasets(projectId),
      api.listFigures(projectId),
      api.listTables(projectId),
      api.datasetLimitations(projectId),
    ]);
    setDatasets(ds as unknown as DatasetRow[]);
    setFigures(figs as unknown as FigureRow[]);
    setTables(tbls as unknown as TableRow[]);
    setLimitations(lim.limitations);
  }, [projectId]);

  useEffect(() => {
    void refresh().catch((err: Error) => setError(err.message));
  }, [refresh]);

  async function onUpload(files: FileList | null) {
    if (!files?.[0]) return;
    setBusy(true);
    setError(null);
    try {
      await api.uploadDataset(projectId, files[0]);
      await refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setBusy(false);
    }
  }

  async function onSynthetic() {
    setBusy(true);
    setError(null);
    try {
      await api.createSyntheticDataset(projectId, {
        name: `Synthetic ${seed}`,
        rows,
        random_seed: seed,
        columns: [
          { name: 'x', type: 'float', min: 0, max: 1, distribution: 'uniform' },
          { name: 'y', type: 'float', min: 0, max: 10, distribution: 'normal' },
          { name: 'group', type: 'category', categories: ['A', 'B'] },
        ],
      });
      await refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Generation failed');
    } finally {
      setBusy(false);
    }
  }

  async function runDescriptive(dataset: DatasetRow) {
    if (!dataset.version?.id) return;
    setBusy(true);
    try {
      const run = await api.runAnalysis(projectId, {
        dataset_version_id: dataset.version.id,
        operation: 'descriptive',
        random_seed: seed,
      });
      await api.createTable(projectId, {
        kind: 'descriptive_stats',
        title: `${dataset.name} descriptive stats`,
        dataset_version_id: dataset.version.id,
        analysis_run_id: run.id,
      });
      await api.createFigure(projectId, {
        kind: 'histogram',
        title: `${dataset.name} histogram`,
        dataset_version_id: dataset.version.id,
        caption: 'Histogram from Dataset Studio',
        alt_text: `Histogram for ${dataset.name}`,
        parameters: { column: Object.keys(dataset.version.profile?.preview_rows?.[0] || {})[0] },
      });
      await refresh();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Analysis failed');
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="space-y-4 rounded-lg border border-[var(--rf-border)] bg-[var(--rf-surface)] p-4">
      <div>
        <h2 className="rf-display text-xl">Dataset Studio</h2>
        <p className="text-xs text-[var(--rf-muted)]">
          Upload real data or generate synthetic data. Analyses never run arbitrary code.
        </p>
      </div>
      {error ? <Notice>{error}</Notice> : null}

      <div className="space-y-2">
        <label className="block text-xs font-medium" htmlFor="dataset-upload">
          Upload CSV / XLSX
        </label>
        <input
          id="dataset-upload"
          type="file"
          accept=".csv,.xlsx"
          disabled={busy}
          onChange={(e) => void onUpload(e.target.files)}
          className="block w-full text-xs"
        />
      </div>

      <div className="space-y-2 rounded border border-dashed border-[var(--rf-border)] p-3">
        <p className="text-xs font-medium">Synthetic generator</p>
        <Notice>{SYNTHETIC_LABEL}</Notice>
        <div className="flex flex-wrap gap-2 text-xs">
          <label>
            Rows{' '}
            <input
              type="number"
              className="w-20 rounded border border-[var(--rf-border)] bg-[var(--rf-bg)] px-1"
              value={rows}
              onChange={(e) => setRows(Number(e.target.value))}
            />
          </label>
          <label>
            Seed{' '}
            <input
              type="number"
              className="w-20 rounded border border-[var(--rf-border)] bg-[var(--rf-bg)] px-1"
              value={seed}
              onChange={(e) => setSeed(Number(e.target.value))}
            />
          </label>
          <Button type="button" size="sm" disabled={busy} onClick={() => void onSynthetic()}>
            Generate
          </Button>
        </div>
      </div>

      <ul className="space-y-3 text-xs">
        {datasets.map((ds) => (
          <li key={ds.id} className="space-y-1 border-t border-[var(--rf-border)] pt-2">
            <p className="font-medium">{ds.name}</p>
            <p className="text-[var(--rf-muted)]">
              {ds.provenance_type}
              {ds.version ? ` · ${ds.version.row_count}×${ds.version.column_count}` : ''}
              {ds.random_seed != null ? ` · seed ${ds.random_seed}` : ''}
            </p>
            <p className="italic">{ds.provenance_label}</p>
            {ds.version?.profile?.pii_warnings?.length ? (
              <p className="text-[var(--rf-danger)]">PII-risk warnings present</p>
            ) : null}
            <div className="flex flex-wrap gap-2">
              <Button
                type="button"
                size="sm"
                variant="secondary"
                onClick={() => void runDescriptive(ds)}
              >
                Analyze + chart
              </Button>
              <Button
                type="button"
                size="sm"
                variant="danger"
                onClick={() => {
                  void api.deleteDataset(projectId, ds.id).then(() => refresh());
                }}
              >
                Delete
              </Button>
            </div>
          </li>
        ))}
        {!datasets.length ? <li className="text-[var(--rf-muted)]">No datasets yet.</li> : null}
      </ul>

      <div className="space-y-2 border-t border-[var(--rf-border)] pt-3">
        <p className="text-xs font-medium">Figures</p>
        <ul className="space-y-1 text-xs">
          {figures.map((fig) => (
            <li key={fig.id} className="flex items-center justify-between gap-2">
              <span>
                Fig. {fig.number}: {fig.title}
                {fig.is_conceptual ? ' (conceptual)' : ''}
              </span>
              <Button
                type="button"
                size="sm"
                variant="secondary"
                disabled={!sectionId}
                onClick={() => {
                  if (!sectionId) return;
                  void api
                    .insertManuscriptAsset(projectId, {
                      section_id: sectionId,
                      asset_type: 'figure',
                      asset_stable_id: fig.stable_id,
                    })
                    .catch((err: Error) => setError(err.message));
                }}
              >
                Insert
              </Button>
            </li>
          ))}
        </ul>
      </div>

      <div className="space-y-2 border-t border-[var(--rf-border)] pt-3">
        <p className="text-xs font-medium">Tables</p>
        <ul className="space-y-1 text-xs">
          {tables.map((table) => (
            <li key={table.id} className="flex items-center justify-between gap-2">
              <span>
                Table {table.number}: {table.title}
              </span>
              <Button
                type="button"
                size="sm"
                variant="secondary"
                disabled={!sectionId}
                onClick={() => {
                  if (!sectionId) return;
                  void api
                    .insertManuscriptAsset(projectId, {
                      section_id: sectionId,
                      asset_type: 'table',
                      asset_stable_id: table.stable_id,
                    })
                    .catch((err: Error) => setError(err.message));
                }}
              >
                Insert
              </Button>
            </li>
          ))}
        </ul>
      </div>

      {limitations.length ? (
        <div className="border-t border-[var(--rf-border)] pt-3 text-[10px] text-[var(--rf-muted)]">
          <p className="font-medium">Scientific limitations</p>
          <ul className="list-disc pl-4">
            {limitations.map((item) => (
              <li key={item}>{item}</li>
            ))}
          </ul>
        </div>
      ) : null}
    </section>
  );
}
